#include <algorithm>
#include <iostream>

// Predicate to compare two pointers by the value they point to
bool int_ptr_less (int* a, int* b) {
    return *a < *b;
}

int main() {
    int x = 17;
    int y = 42;
    int* px = &x;
    int* py = &y;

    // Use custom predicate to find pointer to the larger value
    int* pmax = std::max(px, py, int_ptr_less);

    // Output: 42 (since *py > *px)
    std::cout << *pmax << "\n"; 

    // Default max would compare addresses (usually undefined/unpredictable)
    // int* default_max = std::max(px, py);
}
